  "command": "cd /mnt/session/uploads && python3 - <<'PY'
import json, re, collections
# avg per-row order_items queries per request, bucketed by minute
per_req_min = collections.defaultdict(lambda: collections.defaultdict(int))
for line in open('app.log'):
    if 'order_items WHERE order_id = ?' not in line:
        continue
    try:
        o = json.loads(line)
    except: 
        continue
    m = o['ts'][11:16]
    per_req_min[m][o.get('request_id')] += 1
for m in sorted(per_req_min):
    if not ('14:0' <= m <= '14:45'): 
        continue
    counts = list(per_req_min[m].values())
    reqs = len(counts)
    avg = sum(counts)/reqs
    print(f"{m}  reqs={reqs:3d}  avg_queries/req={avg:5.1f}  max={max(counts)}")
PY"
}
